import { useState } from "react";

export function FaqAccordion({
  question = "{{question}}",
  answer = "{{answer}}",
  density = "{{density}}",
  accent = "{{accent}}",
  firstOpen = {{firstOpen}},
}) {
  const items = [
    { q: question, a: answer, open: firstOpen },
    { q: "Do you offer refunds?", a: "Yes, within 30 days of purchase, no questions asked.", open: false },
    { q: "Is there a free trial?", a: "Every plan includes a 14-day trial, no card required.", open: false },
  ];
  const [openIndex, setOpenIndex] = useState(items.findIndex((i) => i.open));
  const pad = density === "compact" ? "10px 4px" : "16px 4px";
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 480, borderTop: "1px solid #24143018" }}>
      {items.map((item, i) => (
        <div key={item.q} style={{ borderBottom: "1px solid #24143018" }}>
          <button type="button" onClick={() => setOpenIndex(openIndex === i ? -1 : i)} style={{
            width: "100%", textAlign: "left", background: "none", border: "none", cursor: "pointer", padding: pad,
            fontWeight: 600, display: "flex", alignItems: "center", justifyContent: "space-between", color: "inherit", font: "inherit" }}>
            {item.q}
            <span aria-hidden="true" style={{ color: accent }}>{openIndex === i ? "\u2212" : "+"}</span>
          </button>
          {openIndex === i && (
            <p style={{ margin: density === "compact" ? "0 0 10px" : "0 0 16px", fontSize: density === "compact" ? 13 : 14, color: "#241430cc" }}>{item.a}</p>
          )}
        </div>
      ))}
    </div>
  );
}
